from sage.all_cmdline import *   # import sage library

_sage_const_0 = Integer(0); _sage_const_1 = Integer(1); _sage_const_10 = Integer(10); _sage_const_6 = Integer(6); _sage_const_1000 = Integer(1000); _sage_const_7 = Integer(7); _sage_const_3 = Integer(3); _sage_const_2 = Integer(2); _sage_const_5 = Integer(5); _sage_const_4 = Integer(4); _sage_const_100 = Integer(100); _sage_const_4407 = Integer(4407); _sage_const_10000 = Integer(10000); _sage_const_813 = Integer(813); _sage_const_17 = Integer(17)# ---------------------------------------------------------
# <sqrt_nonnegative_existence_uniqueness>（一意性）
#   y_1, y_2 >= 0 かつ y_1^2 = y_2^2 ならば y_1 = y_2
#
# 有理数（厳密演算）で全 pair を走査する。丸めが入らないので同値性を厳密に判定できる。
# 反例探索の方針: 仮定「y >= 0」を外すと一意性は破れる（y と -y）。
# それも合わせて確認し、仮定が効いていることを示す。
# ---------------------------------------------------------
import os
_dir = os.path.dirname(os.path.abspath(__file__)) if '__file__' in dir() else '.'
load(os.path.join(_dir, '../../_shared/operators.sage'))

NONNEG = [QQ(v) for v in [
    _sage_const_0 , _sage_const_1 /_sage_const_10 **_sage_const_6 , _sage_const_1 /_sage_const_1000 , _sage_const_1 /_sage_const_7 , _sage_const_1 /_sage_const_3 , _sage_const_1 /_sage_const_2 , _sage_const_2 /_sage_const_3 , _sage_const_1 , _sage_const_5 /_sage_const_4 , _sage_const_3 /_sage_const_2 , _sage_const_2 , _sage_const_7 /_sage_const_3 , _sage_const_3 , _sage_const_5 , _sage_const_10 ,
    _sage_const_100 , _sage_const_1000 , _sage_const_10 **_sage_const_6 , _sage_const_4407 /_sage_const_10000 , _sage_const_813 /_sage_const_1000 , _sage_const_17 /_sage_const_10 ,
]]

rep = CheckReport("<sqrt_nonnegative_existence_uniqueness> 一意性（y_1,y_2>=0, y_1^2=y_2^2 => y_1=y_2）")

n_pairs = _sage_const_0 
for y1 in NONNEG:
    for y2 in NONNEG:
        n_pairs += _sage_const_1 
        if y1**_sage_const_2  == y2**_sage_const_2 :
            rep.truth(y1 == y2, "y_1=%s, y_2=%s: y_1^2=y_2^2 => y_1=y_2" % (y1, y2))
print("  走査した pair: %d 組" % n_pairs)

# y=0 の場合（本文の場合分け x=0）: y^2=0 => y=0
for y in NONNEG:
    if y**_sage_const_2  == _sage_const_0 :
        rep.truth(y == _sage_const_0 , "y^2=0 => y=0 @y=%s" % y)

# 仮定 y>=0 を外すと破れること
n_broken = _sage_const_0 
for y in NONNEG:
    if y != _sage_const_0  and (-y)**_sage_const_2  == y**_sage_const_2  and (-y) != y:
        n_broken += _sage_const_1 
rep.truth(n_broken == len([y for y in NONNEG if y != _sage_const_0 ]),
          "仮定 y>=0 を外すと非零の全例で一意性が破れる（仮定が効いている）")

rep.finish()

